/* Dissolve (screen-door) support for the game's fragment shaders.
 *
 * Every guest fragment shader gets a `uniform mediump float uLcsDissolve` and a test at the start of main(): a pixel is
 * dropped when an interleaved-gradient noise value is >= the uniform, so 1.0 draws everything and 0.0 nothing. The
 * host sets the uniform on every linked program (rt_dissolve_set), which lets a pass fade geometry in or out without
 * alpha blending. Used to cross-fade the old and new world sector (see recomp/SETTINGS.md).
 *
 * The GL thunks (build/recomp/gl_shims.c, generated by gen_gl.py) call rt_gl_shader_source, rt_gl_link_program and
 * rt_gl_use_program instead of the plain entry points. */
#include "rt.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

extern void *rt_gl_fn[];
extern const char *const rt_gl_names[];
extern int rt_verbose;

static void *gl(const char *name) {
    for (int i = 0; rt_gl_names[i]; i++)
        if (!strcmp(rt_gl_names[i], name)) return rt_gl_fn[i];
    return 0;
}

#define GL_FRAGMENT_SHADER 0x8B30
#define GL_SHADER_TYPE 0x8B4F
#define GL_LINK_STATUS 0x8B82

enum { MAXPROG = 4096 };
static int prog_loc[MAXPROG];      /* uniform location + 1 for programs that carry the dissolve uniform */
static int registered[MAXPROG], nregistered;
static unsigned cur_prog;
static float cur_value = 1.0f;
static int enabled = 1;

static const char *DECL = "uniform mediump float uLcsDissolve;\n";
static const char *TEST =
    "\n    if (uLcsDissolve < 0.999) { mediump float lcsN = fract(dot(gl_FragCoord.xy, vec2(0.7548776662, 0.5698402910))); "
    "if (lcsN >= uLcsDissolve) discard; }\n";

/* returns a malloc'd patched copy of `src`, or 0 when it has no recognisable main() */
static char *patch_fragment(const char *src) {
    const char *m = strstr(src, "void main");
    if (!m) return 0;
    const char *brace = strchr(m, '{');
    if (!brace) return 0;
    size_t n = strlen(src), d = strlen(DECL), t = strlen(TEST);
    char *out = (char *)malloc(n + d + t + 1);
    if (!out) return 0;
    size_t a = (size_t)(m - src), b = (size_t)(brace - src) + 1;
    memcpy(out, src, a);
    memcpy(out + a, DECL, d);
    memcpy(out + a + d, src + a, b - a);
    memcpy(out + a + d + (b - a), TEST, t);
    memcpy(out + a + d + (b - a) + t, src + b, n - b + 1);
    return out;
}

void rt_gl_shader_source(int shader, int count, uintptr_t strs, uintptr_t lens) {
    typedef void (__stdcall *SrcFn)(int, int, uintptr_t, uintptr_t);
    typedef void (__stdcall *IvFn)(int, int, int *);
    static SrcFn src_fn; static IvFn iv_fn;
    if (!src_fn) { src_fn = (SrcFn)gl("glShaderSource"); iv_fn = (IvFn)gl("glGetShaderiv"); }
    int type = 0;
    if (enabled && iv_fn && count > 0 && strs) iv_fn(shader, GL_SHADER_TYPE, &type);
    if (type == GL_FRAGMENT_SHADER) {
        size_t total = 1;
        const char **s = (const char **)strs;
        const int *l = (const int *)lens;
        for (int i = 0; i < count; i++) total += l && l[i] >= 0 ? (size_t)l[i] : strlen(s[i]);
        char *all = (char *)malloc(total);
        if (all) {
            size_t at = 0;
            for (int i = 0; i < count; i++) {
                size_t k = l && l[i] >= 0 ? (size_t)l[i] : strlen(s[i]);
                memcpy(all + at, s[i], k); at += k;
            }
            all[at] = 0;
            char *patched = patch_fragment(all);
            if (patched) {
                const char *one = patched;
                src_fn(shader, 1, (uintptr_t)&one, 0);
                if (getenv("LCS_DUMP_SHADERS")) {
                    char name[64]; snprintf(name, sizeof name, "shader_%d.frag", shader);
                    FILE *f = fopen(name, "wb"); if (f) { fwrite(patched, 1, strlen(patched), f); fclose(f); }
                }
                free(patched); free(all);
                return;
            }
            free(all);
        }
    }
    src_fn(shader, count, strs, lens);
}

static void set_uniform_on(unsigned prog, float v) {
    typedef void (__stdcall *UseFn)(unsigned); typedef void (__stdcall *U1Fn)(int, float);
    static UseFn use; static U1Fn u1;
    if (!use) { use = (UseFn)gl("glUseProgram"); u1 = (U1Fn)gl("glUniform1f"); }
    if (prog >= MAXPROG || !prog_loc[prog]) return;
    use(prog); u1(prog_loc[prog] - 1, v);
}

void rt_gl_link_program(int prog) {
    typedef void (__stdcall *LinkFn)(int); typedef int (__stdcall *LocFn)(int, const char *);
    typedef void (__stdcall *UseFn)(unsigned);
    static LinkFn link; static LocFn loc; static UseFn use;
    if (!link) { link = (LinkFn)gl("glLinkProgram"); loc = (LocFn)gl("glGetUniformLocation"); use = (UseFn)gl("glUseProgram"); }
    link(prog);
    if (!enabled || (unsigned)prog >= MAXPROG) return;
    int l = loc(prog, "uLcsDissolve");
    if (l < 0) { prog_loc[prog] = 0; return; }
    if (!prog_loc[prog]) registered[nregistered++ % MAXPROG] = prog;
    prog_loc[prog] = l + 1;
    set_uniform_on((unsigned)prog, cur_value);
    use(cur_prog);
}

void rt_gl_use_program(int prog) {
    typedef void (__stdcall *UseFn)(unsigned); typedef void (__stdcall *U1Fn)(int, float);
    static UseFn use; static U1Fn u1;
    if (!use) { use = (UseFn)gl("glUseProgram"); u1 = (U1Fn)gl("glUniform1f"); }
    use((unsigned)prog);
    cur_prog = (unsigned)prog;
    if (prog > 0 && prog < MAXPROG && prog_loc[prog] && cur_value != 1.0f) u1(prog_loc[prog] - 1, cur_value);
}

/* 1.0 = draw everything (default), 0.0 = draw nothing */
void rt_dissolve_set(float v) {
    typedef void (__stdcall *UseFn)(unsigned);
    static UseFn use;
    if (!use) use = (UseFn)gl("glUseProgram");
    if (v < 0.0f) v = 0.0f;
    if (v > 1.0f) v = 1.0f;
    if (v == cur_value) return;
    cur_value = v;
    for (int i = 0; i < nregistered && i < MAXPROG; i++) set_uniform_on((unsigned)registered[i], v);
    if (use) use(cur_prog);
}

void rt_dissolve_init(void) {
    const char *e = getenv("LCS_DISSOLVE_TEST"); /* tests: dither the whole scene at this level */
    if (e) cur_value = (float)atof(e);
}
